# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: intake
def intake(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs, offset=4):
    return [v + offset for v in xs]

# region: sift
def sift(xs, offset=4):
    return [v + offset for v in xs]

# region: digest
def digest(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return shape(digest(sift(render(intake(fold(raw))))))

